from config import merged_config


def test_recursive_merge():
    base = {"limits": {"cpu": 1, "mem": 4}, "name": "svc"}
    result = merged_config(base, {"limits": {"mem": 8}, "region": "eu"})
    assert result == {"limits": {"cpu": 1, "mem": 8}, "name": "svc", "region": "eu"}


def test_non_dict_override_replaces():
    base = {"tags": ["a", "b"]}
    result = merged_config(base, {"tags": ["c"]})
    assert result == {"tags": ["c"]}


def test_empty_overrides_returns_equal_config():
    base = {"a": {"b": 1}}
    assert merged_config(base, {}) == base

from copy import deepcopy

from config import merged_config


def test_base_value_unchanged():
    base = {"limits": {"cpu": 1}}
    snapshot = deepcopy(base)
    merged_config(base, {"limits": {"cpu": 99}})
    assert base == snapshot, "base was mutated by the merge"


def test_nested_list_in_base_unchanged():
    base = {"tags": ["prod"]}
    result = merged_config(base, {})
    result["tags"].append("mutated")
    assert base["tags"] == ["prod"], "result shares the nested list with base"


def test_result_independent_of_overrides():
    overrides = {"limits": {"cpu": 2}}
    result = merged_config({"limits": {}}, overrides)
    result["limits"]["cpu"] = 5
    assert overrides["limits"]["cpu"] == 2, "result shares structure with overrides"

"""Identity probes: equality is not enough, the nested objects must be distinct."""
from config import merged_config


def test_nested_dict_is_a_distinct_object():
    base = {"limits": {"cpu": 1}}
    result = merged_config(base, {"other": 1})
    assert result["limits"] == base["limits"]
    assert result["limits"] is not base["limits"], "nested dict is shared by identity"


def test_two_calls_are_independent():
    base = {"limits": {"cpu": 1}}
    a = merged_config(base, {})
    b = merged_config(base, {})
    a["limits"]["cpu"] = 999
    assert b["limits"]["cpu"] == 1, "two results share nested state"


def test_deeply_nested_independence():
    base = {"a": {"b": {"c": [1, 2]}}}
    result = merged_config(base, {})
    result["a"]["b"]["c"].append(3)
    assert base["a"]["b"]["c"] == [1, 2]

